    const rem = str.length - i;
    if (rem === 1) {
      const n = str.charCodeAt(i) << 16;
      out += chars[(n >> 18) & 63] + chars[(n >> 12) & 63] + '==';
    } else if (rem === 2) {
      const n = (str.charCodeAt(i) << 16) | (str.charCodeAt(i + 1) << 8);
