    negotiationReason: q.supplierName === bestSupplier ? null : detectNegotiationReason(q, winnerQ, analysis.risks),
  }));
  const negotiationCandidates = supplierEmails.filter((s) => s.negotiationReason);

  const token = prMessage.id;
  await fastn.state.set('approval:' + token, {
    bestSupplier,
    subjectHeader,
    supplierEmails,
    pendingMessageIds: pending.map((d) => d.id),
  });
  const approveLink = `${APPROVE_BASE}/api/approve?token=${encodeURIComponent(token)}`;

  const negotiationNote = negotiationCandidates.length
    ? `\r\n\r\nNote: ${negotiationCandidates.map((s) => s.supplierName).join(', ')} will receive a counter-request (not a flat rejection) on approval — their price is close to the winner and they're missing exactly one thing (${negotiationCandidates.map((s) => s.negotiationReason).join(', ')}).`
    : '';
  const bodyTextOut = bestSupplier
    ? `Hi,\r\n\r\nYour procurement analysis is attached: the Technical Approval Form and the Procurement Analysis Report, covering ${quoteFiles.length} supplier quotation(s).\r\n\r\nRecommended supplier: ${bestSupplier}.${negotiationNote}\r\n\r\nNothing has been sent to any supplier yet. When you're ready, click below to notify them:\r\n${approveLink}\r\n\r\n— AI Procurement Copilot (automated)`
    : `Hi,\r\n\r\nYour procurement analysis is attached: the Technical Approval Form and the Procurement Analysis Report, covering ${quoteFiles.length} supplier quotation(s).\r\n\r\nNothing has been sent to any supplier yet. When you're ready, click below to notify them:\r\n${approveLink}\r\n\r\n— AI Procurement Copilot (automated)`;

  const boundary = 'fastnBoundary_' + prMessage.id;
  const lines = [];
  lines.push(`To: ${replyTo}`);
  lines.push(`Subject: Re: ${subjectHeader}`);
  if (prMessage.messageIdHeader) {
    lines.push(`In-Reply-To: ${prMessage.messageIdHeader}`);
    lines.push(`References: ${prMessage.messageIdHeader}`);
  }
  lines.push('MIME-Version: 1.0');
  lines.push(`Content-Type: multipart/mixed; boundary="${boundary}"`);
  lines.push('');
  lines.push(`--${boundary}`);
  lines.push('Content-Type: text/plain; charset="UTF-8"');
  lines.push('');
  lines.push(bodyTextOut);
  lines.push('');

  const attachments = [
    { name: taJson.fileName, type: taJson.contentType, base64: taJson.base64 },
    { name: reportJson.fileName, type: reportJson.contentType, base64: reportJson.base64 },
  ];
  for (const a of attachments) {
    lines.push(`--${boundary}`);
    lines.push(`Content-Type: ${a.type}; name="${a.name}"`);
    lines.push('Content-Transfer-Encoding: base64');
    lines.push(`Content-Disposition: attachment; filename="${a.name}"`);
    lines.push('');
    lines.push(wrap76(a.base64));
    lines.push('');
  }
  lines.push(`--${boundary}--`);

  const raw = toBase64Url(lines.join('\r\n'));

  let sendRes;
  try {
    sendRes = await fastn.connector.googleGmail.sendMessage({ raw, threadId: prMessage.threadId });
  } catch (e) {
    return { status: 'error', stage: 'send-failed', error: String(e), retrying: true };
  }

  for (const d of pending) {
    await fastn.connector.googleGmail.modifyMessage({ id: d.id, addLabelIds: [awaitingLabelId] });
  }

  return {
    status: 'awaiting-approval',
    batchSize: pending.length,
    quotationsCompared: quoteFiles.length,
    duplicatesSkipped,
    revisionsApplied,
    bestSupplier,
    negotiationCandidates: negotiationCandidates.map((s) => ({ supplier: s.supplierName, reason: s.negotiationReason })),
    gmailMessageId: sendRes && sendRes.output && sendRes.output.id,
    approveLink,
  };
}
